import React, { useEffect, useState } from 'react';

const PageVisitCounter = () => {
  const [count, setCount] = useState('...');

  useEffect(() => {
    // Busuanzi is a high-speed, professional counting service.
    // It automatically tracks unique visitors based on your domain.
    const script = document.createElement('script');
    script.src = "//busuanzi.ibruce.info/busuanzi/2.3/busuanzi.pure.mini.js";
    script.async = true;
    document.body.appendChild(script);

    // We check the DOM for the value Busuanzi returns
    const checkCount = setInterval(() => {
      const bszValue = document.getElementById('busuanzi_value_site_pv');
      if (bszValue && bszValue.innerText && bszValue.innerText !== '...') {
        setCount(bszValue.innerText);
        clearInterval(checkCount);
      }
    }, 500);

    return () => {
      clearInterval(checkCount);
      document.body.removeChild(script);
    };
  }, []);

  const containerStyle = {
    display: 'inline-flex',
    alignItems: 'center',
    background: '#ffffff',
    padding: '8px 16px',
    borderRadius: '50px',
    border: '1px solid #e0e4e8',
    boxShadow: '0 2px 10px rgba(0,0,0,0.05)',
    fontFamily: '"Segoe UI", Roboto, Helvetica, Arial, sans-serif',
    marginTop: '10px'
  };

  const iconStyle = {
    color: '#004a99', // Banking Blue
    marginRight: '8px',
    fontSize: '1.1rem'
  };

  const textStyle = {
    fontSize: '0.85rem',
    color: '#4a5568',
    fontWeight: '500'
  };

  const numberStyle = {
    color: '#004a99',
    fontWeight: '700',
    marginLeft: '5px',
    fontSize: '0.95rem'
  };

  return (
    <div style={containerStyle}>
      <span style={iconStyle}>📈</span>
      <span style={textStyle}>
        Total Visits: 
        <span id="busuanzi_value_site_pv" style={numberStyle}>{count}</span>
      </span>
    </div>
  );
};

export default PageVisitCounter;
